CREATE FUNCTION pg_temp.hw_apply_40(p_key TEXT, p_data JSONB) RETURNS VOID LANGUAGE plpgsql AS $heroeswatch_81$
DECLARE
  incoming "heroes_watch"."ScenarioConnection"%ROWTYPE;
  existing "heroes_watch"."ScenarioConnection"%ROWTYPE;
BEGIN
  incoming := jsonb_populate_record(NULL::"heroes_watch"."ScenarioConnection", p_data);
  SELECT * INTO existing FROM "heroes_watch"."ScenarioConnection" WHERE "ScenarioConnection_cid" = incoming."ScenarioConnection_cid";
  IF FOUND THEN
    IF incoming."ScenarioConnection_cid" IS NOT NULL AND existing."ScenarioConnection_cid" IS NOT NULL AND incoming."ScenarioConnection_cid" IS DISTINCT FROM existing."ScenarioConnection_cid" THEN
      RAISE EXCEPTION 'Content conflict: %/%.%; existing non-null value retained and import rolled back.', E'ScenarioConnection', p_key, E'ScenarioConnection_cid';
    END IF;
    IF incoming."Game_id" IS NOT NULL AND existing."Game_id" IS NOT NULL AND incoming."Game_id" IS DISTINCT FROM existing."Game_id" THEN
      RAISE EXCEPTION 'Content conflict: %/%.%; existing non-null value retained and import rolled back.', E'ScenarioConnection', p_key, E'Game_id';
    END IF;
    IF incoming."FromScenario_id" IS NOT NULL AND existing."FromScenario_id" IS NOT NULL AND incoming."FromScenario_id" IS DISTINCT FROM existing."FromScenario_id" THEN
      RAISE EXCEPTION 'Content conflict: %/%.%; existing non-null value retained and import rolled back.', E'ScenarioConnection', p_key, E'FromScenario_id';
    END IF;
    IF incoming."ToScenario_id" IS NOT NULL AND existing."ToScenario_id" IS NOT NULL AND incoming."ToScenario_id" IS DISTINCT FROM existing."ToScenario_id" THEN
      RAISE EXCEPTION 'Content conflict: %/%.%; existing non-null value retained and import rolled back.', E'ScenarioConnection', p_key, E'ToScenario_id';
    END IF;
    IF incoming."ConnectionKind" IS NOT NULL AND existing."ConnectionKind" IS NOT NULL AND incoming."ConnectionKind" IS DISTINCT FROM existing."ConnectionKind" THEN
      RAISE EXCEPTION 'Content conflict: %/%.%; existing non-null value retained and import rolled back.', E'ScenarioConnection', p_key, E'ConnectionKind';
    END IF;
    IF incoming."Condition" IS NOT NULL AND existing."Condition" IS NOT NULL AND incoming."Condition" IS DISTINCT FROM existing."Condition" THEN
      RAISE EXCEPTION 'Content conflict: %/%.%; existing non-null value retained and import rolled back.', E'ScenarioConnection', p_key, E'Condition';
    END IF;
    IF (existing."Game_id" IS NULL AND incoming."Game_id" IS NOT NULL)
      OR (existing."FromScenario_id" IS NULL AND incoming."FromScenario_id" IS NOT NULL)
      OR (existing."ToScenario_id" IS NULL AND incoming."ToScenario_id" IS NOT NULL)
      OR (existing."ConnectionKind" IS NULL AND incoming."ConnectionKind" IS NOT NULL)
      OR (existing."Condition" IS NULL AND incoming."Condition" IS NOT NULL) THEN
      UPDATE "heroes_watch"."ScenarioConnection" SET "Game_id" = COALESCE(existing."Game_id", incoming."Game_id"),
        "FromScenario_id" = COALESCE(existing."FromScenario_id", incoming."FromScenario_id"),
        "ToScenario_id" = COALESCE(existing."ToScenario_id", incoming."ToScenario_id"),
        "ConnectionKind" = COALESCE(existing."ConnectionKind", incoming."ConnectionKind"),
        "Condition" = COALESCE(existing."Condition", incoming."Condition")
      WHERE "ScenarioConnection_cid" = incoming."ScenarioConnection_cid";
    END IF;
  ELSE
    INSERT INTO "heroes_watch"."ScenarioConnection" ("ScenarioConnection_cid", "Game_id", "FromScenario_id", "ToScenario_id", "ConnectionKind", "Condition")
    VALUES (incoming."ScenarioConnection_cid", incoming."Game_id", incoming."FromScenario_id", incoming."ToScenario_id", incoming."ConnectionKind", incoming."Condition");
  END IF;
END
